namespace {
struct State {HWND window;win::DesktopAppearance& appearance;};
std::wstring hatch_text(HWND h){const auto n=GetWindowTextLengthW(h);std::wstring value(static_cast<std::size_t>(n)+1,L'\0');GetWindowTextW(h,value.data(),n+1);value.resize(n);return value;}
struct HatchPorts {std::shared_ptr<Ports> files;app::FtnHatchCatalog catalog;unsigned inspected{},catalog_reads{},hatch_reads{};bool present{true};std::vector<app::FileManagementTask> hatches;std::vector<app::FileManagementPending> pending;};
class HatchFake final:public win::IFileAdministrationClient {
    HatchPorts& p;Fake files;
public:
    explicit HatchFake(HatchPorts& value):p(value),files(value.files){}
    bool online()const noexcept override{return true;}
    std::optional<app::FileConfiguration> configuration()override{return files.configuration();}
    std::optional<app::FtnHatchCatalog> ftn_hatch_catalog()override{++p.catalog_reads;return p.catalog;}
    app::FileManagementReadSnapshot read(const app::FileManagementReadRequest& q)override{if(q.kind!=app::FileManagementQueryKind::hatches)return files.read(q);++p.hatch_reads;app::FileManagementReadSnapshot result;result.code=app::LocalAccountResultCode::ok;result.kind=q.kind;for(const auto& row:p.pending)if(row.file==q.selection&&q.pending_after.bytes<row.operation.bytes){if(!result.pending.empty()){result.pending_next=result.pending[0].operation;break;}result.pending.push_back(row);}return result;}
    app::FileManagementJobStatus start(const app::FileManagementTask& t)override{if(t.kind==app::FileManagementTaskKind::hatch_file||t.kind==app::FileManagementTaskKind::reconcile_hatch){p.hatches.push_back(t);app::FileManagementJobStatus r;r.code=app::LocalAccountResultCode::ok;r.job=t.job;r.kind=t.kind;r.state=app::FileManagementJobState::completed;r.journal_confirmed=true;r.result={1};r.detail="Queued for original destinations; delivery not claimed.";return r;}if(t.kind!=app::FileManagementTaskKind::inspect_files)return files.start(t);++p.inspected;app::FileManagementJobStatus result;result.code=app::LocalAccountResultCode::ok;result.job=t.job;result.kind=t.kind;result.state=app::FileManagementJobState::completed;result.inspection=app::FileManagementInspectionPage{};result.inspection->catalog.code=app::LocalAccountResultCode::ok;result.inspection->catalog.records=p.files->files;result.inspection->presence.assign(p.files->files.size(),p.present?app::FilePayloadPresence::present:app::FilePayloadPresence::missing);return result;}
    app::FileManagementJobStatus status(app::Identifier128 id)override{return files.status(id);}
    app::FileManagementJobStatus cancel(app::Identifier128 id)override{return files.cancel(id);}
};
}
#include "native_png_capture.hpp"
namespace {
struct HatchModalDriver {
    DWORD thread=GetCurrentThreadId();HWND owner;win::DesktopAppearance& appearance;std::filesystem::path output;unsigned mode{},stage{};std::atomic<bool> stop{};std::string failure;std::thread worker;
    HatchModalDriver(HWND h,win::DesktopAppearance& a,std::filesystem::path out,unsigned choice):owner(h),appearance(a),output(std::move(out)),mode(choice),worker([this]{while(!stop){EnumThreadWindows(thread,[](HWND h,LPARAM raw)->BOOL{auto& s=*reinterpret_cast<HatchModalDriver*>(raw);if(GetWindow(h,GW_OWNER)!=s.owner||!IsWindowVisible(h)||!GetDlgItem(h,IDOK))return TRUE;const auto title=hatch_text(h);try{
                if(title==L"Hatch File - Network"&&s.stage==0&&GetDlgItem(h,500)){check(SendDlgItemMessageW(h,500,CB_GETCOUNT,0,0)==1,"only enabled network with an AKA offered");State capture{h,s.appearance};render_png(capture,s.output/L"hatch-network.png");++s.stage;SendMessageW(h,WM_COMMAND,s.mode==0?IDCANCEL:IDOK,0);}
                else if(title==L"Hatch File - Echo and Description"&&s.stage==1&&GetDlgItem(h,502)){check(SendDlgItemMessageW(h,500,CB_GETCOUNT,0,0)==1&&SendDlgItemMessageW(h,501,CB_GETCOUNT,0,0)==2,"network-scoped file echo and originating AKA choices");check(hatch_text(GetDlgItem(h,502))==L"Extended text","original description loaded for review");SetDlgItemTextW(h,502,L"Reviewed synthetic file description");State capture{h,s.appearance};render_png(capture,s.output/L"hatch-echo-description.png");++s.stage;SendMessageW(h,WM_COMMAND,IDOK,0);}
                else if(title==L"Choose Hatch Destinations"&&s.stage==2&&GetDlgItem(h,105)){const auto rows=GetDlgItem(h,102);check(ListView_GetItemCount(rows)==1&&!ListView_GetCheckState(rows,0),"only permitted destination listed; none preselected");SendMessageW(h,WM_COMMAND,103,0);check(ListView_GetCheckState(rows,0),"Select All Permitted selects reviewed destination");SendMessageW(h,WM_COMMAND,104,0);check(!ListView_GetCheckState(rows,0),"Clear All removes destination selection");SendMessageW(h,WM_COMMAND,103,0);State capture{h,s.appearance};render_png(capture,s.output/L"hatch-destinations.png");++s.stage;SendMessageW(h,WM_COMMAND,IDOK,0);}
                else if(title==L"Queue Manual Hatch?"&&s.stage==3&&GetDlgItem(h,101)){const auto text=hatch_text(GetDlgItem(h,101));check(text.find(L"My Network")!=text.npos&&text.find(L"Permitted Hub")!=text.npos&&text.find(L"Reviewed synthetic file description")!=text.npos&&text.find(L"Queued does not mean delivered")!=text.npos,"final Queue confirmation has exact choices and delivery limit");GUITHREADINFO focus{sizeof(focus)};check(GetGUIThreadInfo(s.thread,&focus)&&focus.hwndFocus==GetDlgItem(h,IDCANCEL),"Queue confirmation defaults to No");State capture{h,s.appearance};render_png(capture,s.output/L"hatch-final-confirmation.png");++s.stage;SendMessageW(h,WM_COMMAND,s.mode==1?IDCANCEL:IDOK,0);}
                else if(title==L"Hatch Queued"&&s.stage==4&&GetDlgItem(h,101)){check(hatch_text(GetDlgItem(h,101)).find(L"delivery not claimed")!=std::wstring::npos,"authoritative queued result remains separate from delivery");State capture{h,s.appearance};render_png(capture,s.output/L"hatch-queued.png");++s.stage;SendMessageW(h,WM_COMMAND,IDOK,0);}
            }catch(const std::exception& e){s.failure=e.what();s.stop=true;PostMessageW(h,WM_COMMAND,IDCANCEL,0);}return TRUE;},reinterpret_cast<LPARAM>(this));Sleep(5);}}){}
    void finish(){stop=true;worker.join();check(failure.empty(),failure.empty()?"native hatch dialogs completed":failure.c_str());check(stage==(mode==0?1U:mode==1?4U:5U),"complete real hatch modal walkthrough");}
    ~HatchModalDriver(){stop=true;if(worker.joinable())worker.join();}
};
struct PendingHatchDriver {
    DWORD thread=GetCurrentThreadId();HWND owner;win::DesktopAppearance& appearance;std::filesystem::path output;unsigned mode{},reviews{},actions{},confirmations{},results{},new_reviews{};std::atomic<bool> stop{};std::string failure;std::thread worker;
    PendingHatchDriver(HWND h,win::DesktopAppearance& a,std::filesystem::path out,unsigned choice):owner(h),appearance(a),output(std::move(out)),mode(choice),worker([this]{while(!stop){EnumThreadWindows(thread,[](HWND h,LPARAM raw)->BOOL{auto& s=*reinterpret_cast<PendingHatchDriver*>(raw);if(GetWindow(h,GW_OWNER)!=s.owner||!IsWindowVisible(h)||!GetDlgItem(h,IDOK))return TRUE;try{const auto title=hatch_text(h);
        if(title==L"Unfinished Hatch Review"&&GetDlgItem(h,101)){const auto text=hatch_text(GetDlgItem(h,101));check(text.find(L"Original file: file-1.zip")!=text.npos&&text.find(L"Original destinations:")!=text.npos&&text.find(L"Original description:")!=text.npos&&text.find(L"Held")!=text.npos,"unfinished review displays exact source choices and held state");State capture{h,s.appearance};render_png(capture,s.output/(L"pending-review-"+std::to_wstring(++s.reviews)+L".png"));SendMessageW(h,WM_COMMAND,IDOK,0);}
        else if(title==L"Unfinished Hatch"&&GetDlgItem(h,500)){check(SendDlgItemMessageW(h,500,CB_GETCURSEL,0,0)==0,"unfinished action defaults to Cancel");++s.actions;if(s.mode==0){SendMessageW(h,WM_COMMAND,IDOK,0);}else{const int selection=s.mode==3?2:s.reviews==1?3:1;check(SendDlgItemMessageW(h,500,CB_GETCOUNT,0,0)>selection,"multiple unfinished operations require explicit Next selection");SendDlgItemMessageW(h,500,CB_SETCURSEL,selection,0);SendMessageW(h,WM_COMMAND,IDOK,0);}}
        else if(title==L"Retry Original Hatch?"&&GetDlgItem(h,101)){GUITHREADINFO focus{sizeof(focus)};check(GetGUIThreadInfo(s.thread,&focus)&&focus.hwndFocus==GetDlgItem(h,IDCANCEL),"Retry confirmation defaults to No");check(hatch_text(GetDlgItem(h,101)).find(L"Original request two")!=std::wstring::npos,"Retry confirmation preserves selected second original description");State capture{h,s.appearance};render_png(capture,s.output/L"retry-confirmation.png");++s.confirmations;SendMessageW(h,WM_COMMAND,s.mode==1?IDCANCEL:IDOK,0);}
        else if(title==L"Hatch Queued"&&GetDlgItem(h,101)){++s.results;SendMessageW(h,WM_COMMAND,IDOK,0);}
        else if(title==L"Hatch File - Network"&&GetDlgItem(h,500)){++s.new_reviews;SendMessageW(h,WM_COMMAND,IDCANCEL,0);}
    }catch(const std::exception& e){s.failure=e.what();s.stop=true;PostMessageW(h,WM_COMMAND,IDCANCEL,0);}return TRUE;},reinterpret_cast<LPARAM>(this));Sleep(5);}}){}
    void finish(){stop=true;worker.join();check(failure.empty(),failure.empty()?"pending hatch native dialogs completed":failure.c_str());check(reviews==(mode==0||mode==3?1U:2U)&&actions==reviews&&confirmations==(mode==1||mode==2?1U:0U)&&results==(mode==2?1U:0U)&&new_reviews==(mode==3?1U:0U),"explicit pending selection/cancel/retry/new walkthrough completes");}
    ~PendingHatchDriver(){stop=true;if(worker.joinable())worker.join();}
};
}
int main(int argc,char** argv){try{
    check(argc==2,"fresh hatch PNG output required");const auto output=std::filesystem::absolute(argv[1]);check(!std::filesystem::exists(output),"preserve old hatch evidence");std::filesystem::create_directories(output);INITCOMMONCONTROLSEX classes{sizeof(classes),ICC_WIN95_CLASSES};check(InitCommonControlsEx(&classes)!=FALSE,"native controls");
    const auto instance=GetModuleHandleW(nullptr);WNDCLASSEXW cls{sizeof(cls)};cls.lpfnWndProc=ui::State::proc;cls.hInstance=instance;cls.lpszClassName=ui::manager_class;check(RegisterClassExW(&cls)!=0,"shipping FileMan class");
    for(unsigned theme=0;theme<2;++theme){TestAppearance key;if(!theme)key.classic();HatchPorts ports;ports.files=std::make_shared<Ports>();ports.files->files.push_back(row(1));ports.catalog.revision=1;ports.catalog.networks={{"own-net","My Network",{"42:100/1","42:100/1.1"},true},{"off-net","Disabled Network",{"43:100/1"},false}};ports.catalog.echoes={{"own-net","UTILITY.FILES",1}};ports.catalog.destinations={{"own-net","UTILITY.FILES","hub","Permitted Hub"}};
        ui::State s(instance,L"C:\\not-an-installed-hatch-test",L"synthetic-owner",[&](const auto&,const auto&,std::string&)->std::unique_ptr<win::IFileAdministrationClient>{return std::make_unique<HatchFake>(ports);},key.key);s.persist_placement=false;const auto window=CreateWindowExW(WS_EX_TOOLWINDOW,ui::manager_class,L"Section14 Native Hatch Review",WS_OVERLAPPEDWINDOW,-30000,-30000,1100,760,nullptr,nullptr,instance,&s);check(window!=nullptr,"actual FileMan controls");ShowWindow(window,SW_SHOWNOACTIVATE);until(s,[&]{return s.available();});s.command(ui::browse);s.navigate();s.navigate();until(s,[&]{return s.available()&&s.rows.size()==1;});ListView_SetItemState(s.control(ui::entries),0,LVIS_SELECTED|LVIS_FOCUSED,LVIS_SELECTED|LVIS_FOCUSED);s.enable();check(IsWindowEnabled(s.control(ui::hatch_file)),"Hatch File enabled for one available file");
        const auto path=output/(theme?"retro":"classic");std::filesystem::create_directory(path);State capture{window,s.appearance};render_png(capture,path/L"fileman-selected.png");
        {HatchModalDriver driver(window,s.appearance,path,0);s.command(ui::hatch_file);until(s,[&]{return s.available()&&!s.hatch_selection;});driver.finish();}check(ports.inspected==1&&ports.catalog_reads==1&&ports.files->applied==0&&ports.hatches.empty(),"Cancel performs read-only verification, no hatch intent or file mutation");
        {const auto complete=path/L"no";std::filesystem::create_directory(complete);HatchModalDriver driver(window,s.appearance,complete,1);s.command(ui::hatch_file);until(s,[&]{return s.available()&&!s.hatch_selection;});driver.finish();}check(ports.inspected==2&&ports.catalog_reads==2&&ports.files->applied==0&&ports.hatches.empty(),"final No creates no hatch task or intent");
        {const auto complete=path/L"yes";std::filesystem::create_directory(complete);HatchModalDriver driver(window,s.appearance,complete,2);s.command(ui::hatch_file);until(s,[&]{return s.available()&&!s.hatch_selection;});driver.finish();}check(ports.hatches.size()==1&&ports.hatches[0].kind==app::FileManagementTaskKind::hatch_file&&app::valid_file_management_task(ports.hatches[0])&&ports.hatches[0].hatch.file==app::FileId{1}&&ports.hatches[0].hatch.destinations==std::vector<std::string>{"hub"}&&ports.hatches[0].hatch.description=="Reviewed synthetic file description"&&ports.files->applied==0,"explicit Yes submits one exact typed hatch without catalog mutation");
        ports.present=false;s.command(ui::hatch_file);until(s,[&]{return s.available()&&!s.hatch_selection;});check(ports.inspected==4&&ports.catalog_reads==3&&ports.hatches.size()==1,"unverified file refused before destination query or hatch creation");
        ports.present=true;for(unsigned n=1;n<=2;++n){auto original=ports.hatches.front().hatch;original.operation.bytes.fill(0);original.operation.bytes[15]=static_cast<std::uint8_t>(n);original.description=n==1?"Original request one":"Original request two";app::FileManagementPending held;held.operation=original.operation;held.file=original.file;held.area={1};held.state=static_cast<std::uint8_t>(app::FtnHatchState::held);held.filename="file-1.zip";held.detail="Interrupted original copy";held.hatch=original;ports.pending.push_back(held);}
        for(unsigned mode=0;mode<4;++mode){const auto pending_path=path/(L"pending-"+std::to_wstring(mode));std::filesystem::create_directory(pending_path);PendingHatchDriver driver(window,s.appearance,pending_path,mode);s.command(ui::hatch_file);until(s,[&]{return s.available()&&!s.hatch_selection;});driver.finish();check(ports.hatches.size()==(mode<2?1U:2U),"opening/cancelling/declining pending review never submits hatch work");if(mode==2)check(ports.hatches.back().kind==app::FileManagementTaskKind::reconcile_hatch&&ports.hatches.back().target==ports.pending[1].operation&&!ports.hatches.back().hatch.operation.valid()&&ports.inspected==4&&ports.catalog_reads==3,"explicit second Retry sends only original identity with no refreshed choices");}
        check(ports.inspected==5&&ports.catalog_reads==4&&ports.files->applied==0,"separately selected New gets fresh read-only verification; cancel creates no replacement");
        s.close();until(s,[&]{return !s.window;});s.worker.reset();pump();
    }
    std::cout<<"PASS "<<checks<<" native FileMan hatch confirmation/cancel checks; synthetic owner ports, native queue qualified separately\n";return 0;
}catch(const std::exception& e){std::cerr<<"FAIL "<<checks<<": "<<e.what()<<'\n';return 1;}}
